//! DEP-03 §Grounded arms (DEP-18 grounded-arms-v7): the shared vector
//! `tests/vectors/grounded_arms.txt`, generated by cl-deposits from the signet soak's proofs.
//! Each DisputeEnter's grounds class, the cut's grounds step and the confiscation's shape.

use bitcoin::secp256k1::PublicKey;
use deposits_node::node::armers::{
    cut_by_grounds, grounds_class, shape_by_grounds, GroundsClass, Verdict,
};
use std::collections::HashMap;

fn verdict(s: &str) -> Verdict {
    match s {
        "grounded" => Verdict::Grounded,
        "ungrounded" => Verdict::Ungrounded,
        "unknown" => Verdict::Unknown,
        other => panic!("verdict {other}"),
    }
}

fn opt<'a>(f: &'a HashMap<&str, &str>, k: &str) -> Option<&'a str> {
    f.get(k).copied().filter(|v| *v != "-")
}

#[test]
fn grounded_arms_vector() {
    let text = include_str!("vectors/grounded_arms.txt");
    let (mut kind, mut name) = ("", "");
    let mut fields: HashMap<&str, &str> = HashMap::new();
    let mut items: Vec<(String, Verdict)> = Vec::new();
    let mut cases = 0;
    for line in text.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let (head, rest) = line.split_once(' ').unwrap_or((line, ""));
        match head {
            "class" | "cut" | "shape" => {
                kind = head;
                name = rest;
                fields.clear();
                items.clear();
            }
            "enter" if kind == "class" => {
                let w: Vec<&str> = rest.split(' ').collect();
                fields.insert("enter", w[0]);
                fields.insert("expiry", w[2]);
            }
            "enter" | "armer" => {
                let w: Vec<&str> = rest.split(' ').collect();
                items.push((w[0].to_string(), verdict(w[1])));
            }
            "end" => {
                cases += 1;
                let expect = fields["expect"];
                match kind {
                    "class" => {
                        let op = opt(&fields, "operator")
                            .map(|h| PublicKey::from_slice(&hex::decode(h).unwrap()).unwrap());
                        let class = grounds_class(
                            fields["reason"],
                            opt(&fields, "anchor").map(|a| a.parse().unwrap()),
                            opt(&fields, "hash")
                                .map(|h| hex::decode(h).unwrap().try_into().unwrap()),
                            opt(&fields, "proof"),
                            fields["enter"].parse().unwrap(),
                            opt(&fields, "expiry").map(|e| e.parse().unwrap()),
                            op.as_ref(),
                        );
                        let got = match class {
                            GroundsClass::Expiry => "expiry",
                            GroundsClass::Ungrounded(_) => "ungrounded",
                            GroundsClass::Verify(_) => "verify",
                        };
                        assert_eq!(got, expect, "grounded_arms class {name}");
                    }
                    "cut" => {
                        let entries: Vec<(String, Verdict, String)> = items
                            .iter()
                            .map(|(k, v)| (k.clone(), *v, "vector".to_string()))
                            .collect();
                        let got = match cut_by_grounds(fields["ruleset"], &entries) {
                            Ok((kept, _)) if kept.is_empty() => "none".to_string(),
                            Ok((kept, _)) => kept.join(" "),
                            Err(_) => "error".to_string(),
                        };
                        assert_eq!(got, expect, "grounded_arms cut {name}");
                    }
                    "shape" => {
                        let got = match shape_by_grounds(fields["ruleset"], &items) {
                            Ok(true) => "respectful",
                            Ok(false) => "punitive",
                            Err(_) => "error",
                        };
                        assert_eq!(got, expect, "grounded_arms shape {name}");
                    }
                    other => panic!("kind {other}"),
                }
            }
            k => {
                fields.insert(k, rest);
            }
        }
    }
    assert_eq!(cases, 24, "every grounded_arms case ran");
}
